from bcc import BPF, SymbolCache, sym
import ctypes as ct
import time
import sys
import os

# BPF program for counting strlen return values
bpf_count = """
#include <uapi/linux/ptrace.h>

BPF_HISTOGRAM(ret_hist);

int count_strlen_ret(struct pt_regs *ctx) {
    u64 ret = PT_REGS_RC(ctx);
    ret_hist.increment(bpf_log2l(ret));
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_submit_addr = """
#include <uapi/linux/ptrace.h>

struct data_t {
    u64 resolver;
    u64 impl;
};
BPF_PERF_OUTPUT(events);

int submit_addr(struct pt_regs *ctx) {
    struct data_t data = {};
    data.resolver = (u64)PT_REGS_PARM1(ctx);
    data.impl = (u64)PT_REGS_PARM2(ctx);
    events.perf_submit(ctx, &data, sizeof(data));
    return 0;
}
"""

# Helper to get the symbol of the indirect function
def get_indirect_strlen_symbol(libc_path):
    syms = []
    with open(libc_path, "rb") as f:
        for s in sym.get_syms(libc_path):
            if s.name == "strlen":
                syms.append(s)
    if not syms:
        raise Exception("Could not find strlen symbol in libc")
    return syms[0]

# Helper to set the addresses of the resolver and implementation functions
def set_resolver_and_impl_addr(libc_path):
    resolver_addr = None
    impl_addr = None
    for s in sym.get_syms(libc_path):
        if s.name == "__strlen_sse2":
            impl_addr = s.addr
        if s.name == "__strlen_ifunc":
            resolver_addr = s.addr
    if not resolver_addr or not impl_addr:
        raise Exception("Could not find resolver or implementation function")
    return resolver_addr, impl_addr

# Helper to find the offset of the implementation function
def find_impl_offset(libc_path):
    strlen_sym = get_indirect_strlen_symbol(libc_path)
    _, impl_addr = set_resolver_and_impl_addr(libc_path)
    offset = impl_addr - strlen_sym.addr
    return offset

def main():
    libc_path = BPF.Get_libc_path()
    strlen_sym = get_indirect_strlen_symbol(libc_path)
    offset = find_impl_offset(libc_path)
    impl_addr = strlen_sym.addr + offset

    b = BPF(text=bpf_count)
    b.attach_uprobe(name=libc_path, sym="strlen", fn_name="count_strlen_ret", offset=offset)

    print("Tracing strlen return values... Hit Ctrl-C to end.")

    try:
        while True:
            time.sleep(1)
            print("Histogram of strlen return values:")
            b["ret_hist"].print_log2_hist("strlen return")
            b["ret_hist"].clear()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
